            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Mechanics is the paradise of the mathematical sciences because by means of it one comes to the fruits of mathematics.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "I am not to blame for putting forward, in the course of my work on science, any general rule derived from a previous conclusion.", Author = "Leonardo da Vinci" },
