            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "I know that many will call this useless work.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Though I may not, like them, be able to quote other authors, I shall rely on that which is much greater and more worthy — on experience, the mistress of their Masters.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Those men who are inventors and interpreters between Nature and Man, as compared with boasters and declaimers of the works of others, must be regarded and not otherwise esteemed than as the object in front of a mirror, when compared with its image seen in the mirror.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Many will think they may reasonably blame me by alleging that my proofs are opposed to the authority of certain men held in the highest reverence by their inexperienced judgments; not considering that my works are the issue of pure and simple experience, who is the one true mistress.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Among all the studies of natural causes and reasons Light chiefly delights the beholder; and among the great features of Mathematics the certainty of its demonstrations is what preeminently (tends to) elevate the mind of the investigator.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "These rules are of use only in correcting the figures; since every man makes some mistakes in his first compositions and he who knows them not, cannot amend them.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "These rules will enable you to have a free and sound judgment; since good judgment is born of clear understanding, and a clear understanding comes of reasons derived from sound rules, and sound rules are the issue of sound experience — the common mother of all the sciences and arts.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Those who are in love with practice without knowledge are like the sailor who gets into a ship without rudder or compass and who never can be certain whether he is going. Practice must always be founded on sound theory, and to this Perspective is the guide and the gateway; and without this nothing can be done well in the matter of drawing.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The painter who draws merely by practice and by eye, without any reason, is like a mirror which copies every thing placed in front of it without being conscious of their existence.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The eye which turns from a white object in the light of the sun and goes into a less fully lighted place will see everything as dark.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A point is not part of a line.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The smallest natural point is larger than all mathematical points, and this is proved because the natural point has continuity, and any thing that is continuous is infinitely divisible; but the mathematical point is indivisible because it has no size.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Nothing is that which fills no space.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "That which has no limitations, has no form.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The line has in itself neither matter nor substance and may rather be called an imaginary idea than a real object; and this being its nature it occupies no space.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The boundaries of bodies are the least of all things.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Drawing is based upon perspective, which is nothing else than a thorough knowledge of the function of the eye.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Perspective is nothing more than a rational demonstration applied to the consideration of how objects in front of the eye transmit their image to it, by means of a pyramid of lines.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "All objects transmit their image to the eye in pyramids, and the nearer to the eye these pyramids are intersected the smaller will the image appear of the objects which cause them.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The instant the atmosphere is illuminated it will be filled with an infinite number of images which are produced by the various bodies and colours assembled in it. And the eye is the target, a lodestone, of these images.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "All bodies together, and each by itself, give off to the surrounding air an infinite number of images which are all-pervading and each complete, each conveying the nature, colour and form of the body which produces it.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Every body in light and shade fills the surrounding air with infinite images of itself; and these, by infinite pyramids diffused in the air, represent this body throughout space and on every side.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The body of the atmosphere is full of infinite radiating pyramids produced by the objects existing in it.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The air is filled with endless images of the objects distributed in it; and all are represented in all, and all in one, and all in each.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "All objects project their whole image and likeness, diffused and mingled in the whole of the atmosphere, opposite to themselves.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "It is impossible that the eye should project from itself, by visual rays, the visual virtue, since, as soon as it opens, that front portion [of the eye] which would give rise to this emanation would have to go forth to the object and this it could not do without time.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "All the rays which convey the images of objects through the air are straight lines.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "O neglectful Nature, wherefore art thou thus partial, becoming to some of thy children a tender and benignant mother, to others a most cruel and ruthless stepmother?", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Shadow is not the absence of light, merely the obstruction of the luminous rays by an opaque body.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Shadow is the diminution alike of light and of darkness, and stands between darkness and light.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A shadow may be infinitely dark, and also of infinite degrees of absence of darkness. The beginnings and ends of shadow lie between the light and darkness and may be infinitely diminished and infinitely increased. Shadow is the means by which bodies display their form. The forms of bodies could not be understood in detail but for shadow.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Shadow partakes of the nature of universal matter.", Author = "Leonardo da Vinci" },
