            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The outlines and form of any part of a body in light and shade are indistinct in the shadows and in the high lights; but in the portions between the light and the shadows they are highly conspicuous.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A single and distinct luminous body causes stronger relief in the object than a diffused light.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The body which is nearest to the light casts the largest shadow, and why?", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "No small hole can so modify the convergence of rays of light as to prevent, at a long distance, the transmission of the true form of the luminous body causing them.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A shadow will appear dark in proportion to the brilliancy of the light surrounding it and conversely it will be less conspicuous where it is seen against a darker background.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A dark object seen against a bright background will appear smaller than it is. A light object will look larger when it is seen against a background darker than itself.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A luminous body when obscured by a dense atmosphere will appear smaller; as may be seen by the moon or sun veiled by fogs.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Of several luminous bodies of equal size and brilliancy and at an equal distance, that will look the largest which is surrounded by the darkest background.", Author = "Leonardo da Vinci" },
