            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "If you are representing a white body let it be surrounded by ample space, because as white has no colour of its own, it is tinged and altered in some degree by the colour of the objects surrounding it.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A picture or representation of human figures, ought to be done in such a way as that the spectator may easily recognise, by means of their attitudes, the purpose in their minds.", Author = "Leonardo da Vinci" },
