            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The motions of men must be such as suggest their dignity or their baseness.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Represent your figures in such action as may be fitted to express what purpose is in the mind of each; otherwise your art will not be admirable.", Author = "Leonardo da Vinci" },
