            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "We, by our arts may be called the grandsons of God.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Obstacles cannot crush me. Every obstacle yields to stern resolve. He who is fixed to a star does not change his mind.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Ivy is of longevity.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Fire destroys falsehood, that is sophistry, and restores truth, driving out darkness.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Truth at last cannot be hidden. Dissimulation is of no avail. Dissimulation is to no purpose before so great a judge. Falsehood puts on a mask. Nothing is hidden under the sun.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Movement will cease before we are weary of being useful.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Constancy does not begin, but is that which perseveres.", Author = "Leonardo da Vinci" },
