            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The soul seems to reside in the judgment, and the judgment would seem to be seated in that part where all the senses meet; and this is called the Common Sense and is not all-pervading throughout the body, as many have thought.", Author = "Leonardo da Vinci" },
