            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Men born in hot countries love the night because it refreshes them and have a horror of light because it burns them; and therefore they are of the colour of night, that is black.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Thou, O God, dost sell us all good things at the price of labour.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Necessity is the mistress and guide of nature.", Author = "Leonardo da Vinci" },
