            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Experience, the interpreter between formative nature and the human race, teaches how that nature acts among mortals; and being constrained by necessity cannot act otherwise than as reason, which is its helm, requires her to act.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Wisdom is the daughter of experience.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Nature is full of infinite causes that have never occurred in experience.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Truth was the daughter of Time.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Experience never errs; it is only your judgments that err by promising themselves effects such as are not caused by your experiments.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Any one who in discussion relies upon authority uses, not his understanding, but rather his memory.", Author = "Leonardo da Vinci" },
