            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "O Time! consumer of all things; O envious age! thou dost destroy all things and devour all things with the relentless teeth of years, little by little in a slow death.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "O sleepers! what a thing is slumber! Sleep resembles death. Ah, why then dost thou not work in such wise as that after death thou mayst retain a resemblance to perfect life, when, during life, thou art in sleep so like to the hapless dead?", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "The knowledge of past times and of the places on the earth is both an ornament and nutriment to the human mind.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "To lie is so vile, that even if it were in speaking well of godly things it would take off something from God's grace; and Truth is so excellent, that if it praises but small things they become noble.", Author = "Leonardo da Vinci" },
